// ---------- 4. 后端进程管理 ----------
let backend = null;
function startBackend(keyId, privateKey) {
  return new Promise((resolve, reject) => {
    const child = spawn('java', ['-Dfile.encoding=UTF-8', '-Dserver.port=8080', '-jar', WAR], {
      cwd: path.resolve(VUE_ROOT, '../demo_new-facade'),
      env: Object.assign({}, process.env, {
        BWAPP_SYS_TRANSPORTV2_[REDACTED CREDENTIAL]
        BWAPP_SYS_TRANSPORTV2_KEY_ID: keyId,
      }),
      stdio: ['ignore', fs.openSync(path.join(KEYS, 'b1-be.log'), 'a'), fs.openSync(path.join(KEYS, 'b1-be.log'), 'a')],
    });
    backend = child;
    const started = Date.now();
    (function poll() {
      if (Date.now() - started > 120000) return reject(new Error('后端启动超时'));
      http.get(BE + CONTEXT + '/transport/v2/pubkey', res => {
        res.resume();
        if (res.statusCode === 200) resolve(child); else setTimeout(poll, 1000);
      }).on('error', () => setTimeout(poll, 1000));
    })();
  });
}
function stopBackend() {
  return new Promise(resolve => {
    if (!backend) return resolve();
    const pid = backend.pid;
    try { execSync('taskkill /PID ' + pid + ' /T /F', { stdio: 'ignore' }); } catch (e) { /* 已退出 */ }
    const wait = Date.now();
    (function poll() {
      http.get(BE + CONTEXT + '/transport/v2/pubkey', () => setTimeout(poll, 500))
        .on('error', () => resolve());
      if (Date.now() - wait > 30000) resolve();
    })();
  });
}
function publishedKey() {
  return new Promise((resolve, reject) => {
    http.get(BE + CONTEXT + '/transport/v2/pubkey', res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { try { resolve(JSON.parse(d).data); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

